import {WATER_LEVEL,roadX,onTrail,slopeAt} from './core.js?v=2.25-drive-grass1';
export function footSurface(p,colliders=[]){for(const c of colliders)if(c.bridge&&c.indoor&&Math.abs(p.x-c.x)<c.w/2+.02&&Math.abs(p.z-c.z)<c.d/2+.02&&Math.abs(p.ground-c.y-c.h)<.16)return c.surface==='stone'?'stone':'wood';if(p.ground<WATER_LEVEL-.1)return 'water';if(Math.abs(p.x-roadX(p.z))<4||onTrail(p.x,p.z,.2))return 'gravel';return slopeAt(p.x,p.z)>.60?'stone':'grass';}
export class FootstepContacts{constructor(){this.reset();}reset(){this.previous=null;this.distance=0;this.side=-1;}update(dt,p,{active=false,moving=false,swimming=false,sprinting=false}={}){const last=this.previous;this.previous={x:p.x,z:p.z};if(!last||dt<=0||!active||!moving||swimming||(p.jump||0)>.03){this.distance=0;return null;}const travel=Math.hypot(p.x-last.x,p.z-last.z);if(travel>Math.max(.5,dt*12)){this.distance=0;return null;}this.distance+=travel;const stride=p.crouch?1.18:sprinting?2.25:1.8;if(this.distance+1e-9<stride)return null;this.distance=Math.max(0,this.distance-stride);this.side*=-1;return {side:this.side,crouching:!!p.crouch,sprinting};}}
